import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"Rclone S3 Timestamp 模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/modules/rclone-s3-timestamp.md","filePath":"zh-Hans/deep-dive/modules/rclone-s3-timestamp.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/modules/rclone-s3-timestamp.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="rclone-s3-timestamp-模块" tabindex="-1">Rclone S3 Timestamp 模块 <a class="header-anchor" href="#rclone-s3-timestamp-模块" aria-label="Permalink to “Rclone S3 Timestamp 模块”">​</a></h1><p>当 Sync Engine 使用 S3 后端搭配 <a href="https://rclone.org/commands/rclone_serve_s3/" target="_blank" rel="noreferrer"><code>rclone serve s3</code></a> 时，本模块保留文件的修改时间。选择 S3 后端时它自动生效。</p><h2 id="修改时间" tabindex="-1">修改时间 <a class="header-anchor" href="#修改时间" aria-label="Permalink to “修改时间”">​</a></h2><p>Sync Engine 以毫秒存储 <code>mtime</code>，而 rclone 把 <code>x-amz-meta-mtime</code> 解释为 Unix 秒。模块在线路上双向转换这个头：上传把毫秒转换为秒（例如 <code>1700000123456</code> 转为 <code>1700000123.456</code>），下载把秒转换回毫秒。</p><p>转换只作用于可解析的值：上传只转换形如 Sync Engine 时间戳的值（13 位毫秒）；下载只转换数值。服务器重启导致 <code>rclone serve s3</code> 丢失内存元数据、省略 <code>x-amz-meta-mtime</code> 时，S3 后端会自行从 <code>Last-Modified</code> 恢复时间。</p><h2 id="加密" tabindex="-1">加密 <a class="header-anchor" href="#加密" aria-label="Permalink to “加密”">​</a></h2><p>启用<a href="./encryption">加密</a>时，其包装器（优先级 7919）在 S3 后端把元数据变成 <code>x-amz-meta-*</code> 头之前先加密元数据。加密后的 <code>mtime</code> 不是数值，因此本模块保持它不变；解密在读回时恢复毫秒值。</p><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to “实现”">​</a></h2><p>模块以优先级 <code>307</code> 注册远端请求中间件，位于 S3 SigV4 中间件（<code>304</code>）之外，让请求签名覆盖转换后的值；位于重试中间件（<code>2000</code>）之内，让每次重试都从原始参数转换。中间件重建请求和响应而不是原地修改，其余每个头都不受影响。</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};